function createBufferPool(size, count) {
  const free = Array.from({ length: count }, () => Buffer.allocUnsafe(size));
  return {
    acquire() { return free.pop() ?? Buffer.allocUnsafe(size); },
    release(buf) { buf.fill(0); free.push(buf); },
  };
}
const pool = createBufferPool(64 * 1024, 32);

// Hot path — avoid
